93	/****************************************************************************
94	 * Private Functions - Register Access Helpers
95	 ****************************************************************************/
96	
97	static inline uint32_t getreg32(uintptr_t addr)
98	{
99	  return *(volatile uint32_t *)addr;
100	}
101	
102	static inline void putreg32(uint32_t val, uintptr_t addr)
103	{
104	  *(volatile uint32_t *)addr = val;
105	}
106	
107	static void reset_assert(unsigned int id)
108	{
109	  unsigned int bank = id / 32;
110	  unsigned int bit = id % 32;
111	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
112	
113	  putreg32(reg & ~(1u << bit), REG_RESET_BANK(bank));
114	}
115	
116	static void reset_deassert(unsigned int id)
117	{
118	  unsigned int bank = id / 32;
119	  unsigned int bit = id % 32;
120	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
121	
122	  putreg32(reg | (1u << bit), REG_RESET_BANK(bank));
123	}
124	
125	static void clk_reset_deassert(unsigned int id)
126	{
127	  unsigned int bank = id / 32;
128	  unsigned int bit = id % 32;
129	  uintptr_t addr = SG2000_CLKGEN_BASE + bank * 4;
130	  uint32_t reg = getreg32(addr);
131	
132	  putreg32(reg | (1u << bit), addr);
133	}
