882	/****************************************************************************
883	 * Private Functions — MAC Address Configuration
884	 *
885	 * Reference: Manual §4.4 Step 6, §10.3 Phase 5.3
886	 ****************************************************************************/
887	
888	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
889	{
890	  uint32_t hi;
891	  uint32_t lo;
892	
893	  hi = ((uint32_t)mac[5] << 8) | (uint32_t)mac[4] | GMAC_HI_REG_AE;
894	  lo = ((uint32_t)mac[3] << 24) | ((uint32_t)mac[2] << 16) |
895	       ((uint32_t)mac[1] << 8)  | (uint32_t)mac[0];
896	
897	  putreg32(hi, gmac_base + GMAC_MAC_ADDR0_HIGH);
898	  putreg32(lo, gmac_base + GMAC_MAC_ADDR0_LOW);
899	
900	  ethinfo("MAC addr set: %02x:%02x:%02x:%02x:%02x:%02x\n",
901	          mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
902	}
903	
904	/****************************************************************************
905	 * Private Functions — MAC Core and DMA Initialization
906	 *
907	 * Performs the full hardware initialization sequence:
908	 *   - DMA bus mode and AXI configuration
909	 *   - MAC core init (GMAC_CONTROL, interrupt mask, frame filter)
910	 *   - DMA operation mode (Store-and-Forward)
911	 *   - Interrupt enable
912	 *   - Write descriptor base addresses
913	 *   - Start DMA TX and RX
914	 *
915	 * Reference: Manual §10.3 Phase 2, 5, 6, 7
916	 ****************************************************************************/
917	
918	static int hw_setup(struct sg2000_eth_priv_s *priv)
919	{
920	  uintptr_t gmac_base = priv->gmac_base;
921	  uint32_t val;
922	
923	  /* --- Phase 2: DMA software reset --- */
924	
925	  if (dma_soft_reset(gmac_base) < 0)
926	    {
927	      return -ETIMEDOUT;
928	    }
929	
930	  /* --- Phase 2.2: Configure DMA Bus Mode ---
931	   * PBL=8, RPBL=8, FB=1 (fixed burst), USP=1 (separate PBL),
932	   * AAL=1 (address-aligned beats).  ATDS is NOT set (basic descriptors).
933	   */
934	
935	  val = DMA_PBL_8 | (DMA_PBL_8 & 0x3f) << DMA_RPBL_SHIFT |
936	        DMA_FB | DMA_USP | DMA_AAL;
937	  putreg32(val, gmac_base + DMA_BUS_MODE);
938	
939	  /* --- Phase 2.3: Configure AXI bus ---
940	   * WR_OSR_LMT=1, RD_OSR_LMT=2, BLEN support for 4/8/16 beats.
941	   */
942	
943	  putreg32((1 << DMA_AXI_WR_OSR_LMT_SHIFT) |
944	           (2 << DMA_AXI_RD_OSR_LMT_SHIFT) |
945	           (0xf << DMA_AXI_BLEN_SHIFT),
946	           gmac_base + DMA_AXI_BUS_MODE);
947	
948	  ethinfo("DMA: bus_mode=0x%08" PRIX32 " axi=0x%08" PRIX32 "\n",
949	          getreg32(gmac_base + DMA_BUS_MODE),
950	          getreg32(gmac_base + DMA_AXI_BUS_MODE));
951	
952	  /* --- Phase 5.1: Configure GMAC_CONTROL --- */
953	
954	  putreg32(GMAC_CORE_INIT, gmac_base + GMAC_CONTROL);
955	
956	  /* --- Phase 5.2: Configure GMAC_INT_MASK (disable all MAC interrupts,
957	   *   use DMA interrupts only) ---
958	   */
959	
960	  putreg32(GMAC_INT_DEFAULT_MASK, gmac_base + GMAC_INT_MASK);
961	
962	  /* --- Phase 5.4: Configure frame filter ---
963	   * Use promiscuous mode (PR) to accept all packets.  This matches the
964	   * old driver's setup and avoids MAC address filtering issues.
965	   */
966	
967	  putreg32(GMAC_FILTER_PR | GMAC_FILTER_HMC | GMAC_FILTER_PM,
968	           gmac_base + GMAC_FRAME_FILTER);
969	
970	  /* Clear VLAN tag */
971	
972	  putreg32(0, gmac_base + GMAC_VLAN_TAG);
973	
974	  /* Clear pending MAC and DMA interrupts */
975	
976	  putreg32(0xffffffff, gmac_base + GMAC_INT_STATUS);
977	  putreg32(DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
978	
979	  /* --- Phase 5.5: Enable MAC TX and RX --- */
980	
981	  val = getreg32(gmac_base + GMAC_CONTROL);
982	  putreg32(val | GMAC_CONTROL_TE | GMAC_CONTROL_RE, gmac_base + GMAC_CONTROL);
983	
984	  /* --- Phase 6.1: Configure DMA operation mode ---
985	   * RSF=1 (RX Store-and-Forward), TSF=1 (TX Store-and-Forward),
986	   * OSF=1 (Operate on Second Frame), RTC=64, TTC=64.
987	   */
988	
989	  val = getreg32(gmac_base + DMA_CONTROL);
990	  val |= DMA_CONTROL_RSF | DMA_CONTROL_TSF | DMA_CONTROL_OSF |
991	         DMA_CONTROL_RTC_64 | DMA_CONTROL_TTC_64;
992	  putreg32(val, gmac_base + DMA_CONTROL);
993	
994	  /* --- Phase 6.2: Enable DMA interrupts --- */
995	
996	  putreg32(DMA_INTR_DEFAULT_MASK, gmac_base + DMA_INTR_ENA);
997	
998	  /* --- Phase 7.1: Write descriptor base addresses --- */
999	
1000	  putreg32(priv->tx_desc_phys, gmac_base + DMA_TX_BASE_ADDR);
1001	  putreg32(priv->rx_desc_phys, gmac_base + DMA_RCV_BASE_ADDR);
1002	
1003	  /* --- Phase 7.2-7.3: Start DMA TX and RX ---
1004	   * Write ST first, then SR separately with a delay.  The hardware
1005	   * may ignore SR if written simultaneously with ST.
1006	   */
1007	
1008	  val = getreg32(gmac_base + DMA_CONTROL);
1009	  putreg32(val | DMA_CONTROL_ST, gmac_base + DMA_CONTROL);
1010	  up_udelay(10);
1011	
1012	  val = getreg32(gmac_base + DMA_CONTROL);
1013	  putreg32(val | DMA_CONTROL_SR, gmac_base + DMA_CONTROL);
1014	  up_udelay(10);
1015	
1016	  ethinfo("MAC/DMA started: gmac_ctrl=0x%08" PRIX32
1017	          " dma_ctrl=0x%08" PRIX32 " dma_status=0x%08" PRIX32
1018	          " dma_intr=0x%08" PRIX32 "\n",
1019	          getreg32(gmac_base + GMAC_CONTROL),
1020	          getreg32(gmac_base + DMA_CONTROL),
1021	          getreg32(gmac_base + DMA_STATUS),
1022	          getreg32(gmac_base + DMA_INTR_ENA));
1023	
1024	  return OK;
1025	}
1026	
1027	/****************************************************************************
1028	 * Name: gmac_set_speed_duplex
1029	 *
1030	 * Description:
1031	 *   Configure GMAC speed and duplex mode based on PHY negotiation result.
1032	 *
1033	 * Reference: Manual §10.9
1034	 ****************************************************************************/
1035	
1036	static void gmac_set_speed_duplex(uintptr_t gmac_base, int speed, int duplex)
1037	{
1038	  uint32_t val;
1039	
1040	  val = getreg32(gmac_base + GMAC_CONTROL);
1041	
1042	  /* Clear speed and duplex bits */
1043	
1044	  val &= ~(GMAC_CONTROL_FES | GMAC_CONTROL_DM);
1045	
1046	  /* Set speed: FES=1 for 100Mbps, FES=0 for 10Mbps */
1047	
1048	  if (speed == 100)
1049	    {
1050	      val |= GMAC_CONTROL_FES;
1051	    }
1052	
1053	  /* Set duplex: DM=1 for full duplex */
1054	
1055	  if (duplex)
1056	    {
1057	      val |= GMAC_CONTROL_DM;
1058	    }
1059	
1060	  putreg32(val, gmac_base + GMAC_CONTROL);
1061	}
1062	
1063	/****************************************************************************
1064	 * Private Functions — DMA Doorbell
1065	 *
1066	 * Writing any value to DMA_XMT_POLL_DEMAND / DMA_RCV_POLL_DEMAND
1067	 * triggers the DMA engine to re-fetch descriptors from the ring.
1068	 *
1069	 * Reference: Manual §2.3, §10.4, §10.5
1070	 ****************************************************************************/
1071	
1072	static void tx_doorbell(uintptr_t gmac_base)
1073	{
1074	  putreg32(0, gmac_base + DMA_XMT_POLL_DEMAND);
1075	}
1076	
1077	static void rx_doorbell(uintptr_t gmac_base)
1078	{
1079	  putreg32(0, gmac_base + DMA_RCV_POLL_DEMAND);
1080	}
1081	
1082	/****************************************************************************
1083	 * Private Functions — Hardware Transmit
1084	 *
1085	 * Prepares a TX descriptor, copies data to the DMA buffer, and signals
1086	 * the DMA engine to transmit.
1087	 *
1088	 * Reference: Manual §5.2, §10.4
1089	 ****************************************************************************/
1090	
1091	static int hw_transmit(struct sg2000_eth_priv_s *priv,
1092	                       const uint8_t *data, unsigned int len)
1093	{
1094	  uintptr_t gmac_base = priv->gmac_base;
1095	  unsigned int idx = priv->tx_cur;
1096	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
1097	  irqstate_t flags;
1098	
1099	  /* Check if ring is full */
1100	
1101	  if (desc->des0 & TDES0_OWN)
1102	    {
1103	      return -EBUSY;
1104	    }
1105	
1106	  /* Copy data to pre-allocated TX DMA buffer */
1107	
1108	  memcpy(priv->tx_buf[idx], data, len);
1109	
1110	  /* Write back TX buffer so DMA can see packet data */
1111	
1112	  dcache_clean_range((uintptr_t)priv->tx_buf[idx],
1113	                     (uintptr_t)priv->tx_buf[idx] + len);
1114	
1115	  /* Fill descriptor (basic format, 16 bytes):
1116	   *   des0: OWN + IC
1117	   *   des1: buffer size + FS + LS + END_RING + IC
1118	   *   des2: buffer physical address
1119	   */
1120	
1121	  desc->des2 = priv->tx_buf_phys[idx];
1122	  desc->des1 = (len & TDES1_BUFFER1_SIZE_MASK) |
1123	               TDES1_FIRST_SEGMENT | TDES1_LAST_SEGMENT |
1124	               TDES1_END_RING | TDES1_INTERRUPT;
1125	
1126	  /* Memory barrier: ensure descriptor writes are visible to DMA
1127	   * before setting OWN=1.
1128	   */
1129	
1130	  dcache_clean_range((uintptr_t)desc,
1131	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1132	  __asm__ volatile ("fence w,w" ::: "memory");
1133	
1134	  /* Give ownership to DMA.  IC and END_RING are set in des1 above. */
1135	
1136	  desc->des0 = TDES0_OWN;
1137	
1138	  dcache_clean_range((uintptr_t)desc,
1139	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1140	
1141	  /* Advance TX pointer and ring doorbell */
1142	
1143	  flags = up_irq_save();
1144	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1145	  tx_doorbell(gmac_base);
1146	  up_irq_restore(flags);
1147	
1148	  ethinfo("TX: %u bytes desc[%u] des0=0x%08" PRIX32
1149	          " des1=0x%08" PRIX32 " des2=0x%08" PRIX32
1150	          " dma_status=0x%08" PRIX32 "\n",
1151	          len, idx, desc->des0, desc->des1, desc->des2,
1152	          getreg32(gmac_base + DMA_STATUS));
1153	
1154	  return OK;
1155	}
1156	
1157	/****************************************************************************
1158	 * Private Functions — TX Cleanup
1159	 *
1160	 * Frees completed TX packets by walking from dirty_tx to cur_tx.
1161	 * Called from ISR on TX Complete interrupt.
1162	 *
1163	 * Reference: Manual §5.3, §10.4 step 7
1164	 ****************************************************************************/
1165	
1166	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
1167	{
1168	  irqstate_t flags = up_irq_save();
1169	
1170	  while (priv->tx_dirty != priv->tx_cur)
1171	    {
1172	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
1173	
1174	      /* Invalidate descriptor cache line to read DMA-written status */
1175	
1176	      dcache_invalidate_range((uintptr_t)desc,
1177	                              (uintptr_t)desc +
1178	                              sizeof(struct sg2000_dma_desc_s));
1179	
1180	      if (desc->des0 & TDES0_OWN)
1181	        {
1182	          break;  /* Still owned by DMA */
1183	        }
1184	
1185	      /* Check for TX errors */
1186	
1187	      if (desc->des0 & TDES0_ERROR_SUMMARY)
1188	        {
1189	          etherr("TX error desc[%u] status=0x%08" PRIX32 "\n",
1190	                 priv->tx_dirty, desc->des0);
1191	        }
1192	
1193	      /* Free the tracked netpkt and notify upper half */
1194	
1195	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
1196	        {
1197	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
1198	          priv->tx_pkt[priv->tx_dirty] = NULL;
1199	          netdev_lower_txdone(&priv->dev);
1200	        }
1201	
1202	      /* Clear descriptor for reuse, END_RING=1 on all (CV181x convention) */
1203	
1204	      desc->des0 = 0;
1205	      desc->des1 = TDES1_END_RING;
1206	
1207	      dcache_clean_range((uintptr_t)desc,
1208	                         (uintptr_t)desc +
1209	                         sizeof(struct sg2000_dma_desc_s));
1210	
1211	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1212	    }
1213	
1214	  up_irq_restore(flags);
1215	}
1216	
1217	/****************************************************************************
1218	 * Private Functions — Interrupt Service Routine
1219	 *
1220	 * Reads DMA_STATUS to determine interrupt cause and dispatches accordingly.
1221	 * All DMA status bits are write-1-to-clear.
1222	 *
1223	 * Reference: Manual §7, §10.6
1224	 ****************************************************************************/
1225	
1226	static int sg2000_eth_isr(int irq, void *context, void *arg)
1227	{
1228	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1229	  uintptr_t gmac_base = priv->gmac_base;
1230	  uint32_t status;
1231	  uint32_t mac_status;
1232	
1233	  /* Read and clear MAC interrupts (if any) */
1234	
1235	  mac_status = getreg32(gmac_base + GMAC_INT_STATUS);
1236	  if (mac_status)
1237	    {
1238	      putreg32(mac_status, gmac_base + GMAC_INT_STATUS);
1239	    }
1240	
1241	  /* Read DMA status masked by enabled interrupts */
1242	
1243	  status = getreg32(gmac_base + DMA_STATUS) &
1244	           getreg32(gmac_base + DMA_INTR_ENA);
1245	
1246	  if (!status)
1247	    {
1248	      return OK;
1249	    }
1250	
1251	  ethinfo("ISR: dma_status=0x%08" PRIX32 "\n", status);
1252	
1253	  /* Write-1-to-clear the status bits */
1254	
1255	  putreg32(status & DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
1256	
1257	  /* Handle normal interrupts */
1258	
1259	  if (status & DMA_STATUS_NIS)
1260	    {
1261	      /* Receive interrupt: notify upper half */
1262	
1263	      if (status & DMA_STATUS_RI)
1264	        {
1265	          netdev_lower_rxready(&priv->dev);
1266	        }
1267	
1268	      /* Transmit complete: clean up descriptors */
1269	
1270	      if (status & DMA_STATUS_TI)
1271	        {
1272	          tx_cleanup(priv);
1273	        }
1274	    }
1275	
1276	  /* Handle abnormal interrupts */
1277	
1278	  if (status & DMA_STATUS_AIS)
1279	    {
1280	      if (status & DMA_STATUS_FBI)
1281	        {
1282	          etherr("Fatal Bus Error! bus_mode=0x%08" PRIX32
1283	                 " dma_status=0x%08" PRIX32 "\n",
1284	                 getreg32(gmac_base + DMA_BUS_MODE), status);
1285	        }
1286	
1287	      if (status & DMA_STATUS_TU)
1288	        {
1289	          ethwarn("TX Buffer Unavailable\n");
1290	        }
1291	
1292	      if (status & DMA_STATUS_RU)
1293	        {
1294	          ethwarn("RX Buffer Unavailable\n");
1295	        }
1296	
1297	      if (status & DMA_STATUS_TPS)
1298	        {
1299	          ethwarn("TX Process Stopped\n");
1300	        }
1301	
1302	      if (status & DMA_STATUS_RPS)
1303	        {
1304	          ethwarn("RX Process Stopped\n");
1305	        }
1306	
1307	      if (status & DMA_STATUS_OVF)
1308	        {
1309	          ethwarn("RX Overflow\n");
1310	        }
1311	
1312	      if (status & DMA_STATUS_UNF)
1313	        {
1314	          ethwarn("TX Underflow\n");
1315	        }
1316	    }
1317	
1318	  return OK;
1319	}
1320	
1321	/****************************************************************************
1322	 * Name: netdriver_ifup
1323	 *
1324	 * Description:
1325	 *   OpenVela netdev_ops_s ifup callback.  Performs the full hardware
1326	 *   initialization sequence and brings the interface online.
1327	 *
1328	 * Reference: Manual §4.3, §10.3, §10.11
1329	 ****************************************************************************/
1330	
1331	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1332	{
1333	  FAR struct sg2000_eth_priv_s *priv =
1334	      (FAR struct sg2000_eth_priv_s *)dev;
1335	  int ret;
1336	
1337	  ethinfo("ifup begin\n");
1338	
1339	  /* 1. Enable clocks and deassert resets */
1340	
1341	  gmac_clock_enable();
1342	
1343	  /* 2. Set GMAC_CORE_INIT (includes PS=MII mode) before PHY operations */
1344	
1345	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONTROL);
1346	
1347	  /* 3. Initialize EPHY via APB */
1348	
1349	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1350	
1351	  /* 4. Verify MDIO communication with PHY */
1352	
1353	  ret = mdio_verify_phy(priv->gmac_base);
1354	  if (ret < 0)
1355	    {
1356	      etherr("PHY not responding: %d\n", ret);
1357	      return ret;
1358	    }
1359	
1360	  ethinfo("MDIO operational, mdio_addr=0x%08" PRIX32
1361	          " mdio_data=0x%08" PRIX32 "\n",
1362	          getreg32(priv->gmac_base + GMAC_MII_ADDR),
1363	          getreg32(priv->gmac_base + GMAC_MII_DATA));
1364	
1365	  /* 5. Run EPHY full analog tuning (requires operational MDIO) */
1366	
1367	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1368	
1369	  /* 6. Allocate DMA resources (once) */
1370	
1371	  ret = alloc_dma(priv);
1372	  if (ret < 0)
1373	    {
1374	      etherr("alloc_dma failed: %d\n", ret);
1375	      return ret;
1376	    }
1377	
1378	  /* 7. Initialize descriptor rings */
1379	
1380	  init_desc_rings(priv);
1381	
1382	  /* 8. Set MAC address */
1383	
1384	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1385	
1386	  /* 9. Hardware setup: DMA, MAC core, interrupts, start DMA */
1387	
1388	  ret = hw_setup(priv);
1389	  if (ret < 0)
1390	    {
1391	      etherr("hw_setup failed: %d\n", ret);
1392	      return ret;
1393	    }
1394	
1395	  /* 10. Configure PHY (auto-negotiation) and apply speed/duplex */
1396	
1397	  ret = phy_config_init(priv);
1398	  if (ret < 0)
1399	    {
1400	      etherr("PHY config failed: %d\n", ret);
1401	      return ret;
1402	    }
1403	
1404	  /* Apply negotiated speed/duplex to GMAC */
1405	
1406	  gmac_set_speed_duplex(priv->gmac_base, priv->speed, priv->duplex);
1407	
1408	  /* 11. Ring RX doorbell and enable interrupts */
1409	
1410	  rx_doorbell(priv->gmac_base);
1411	  up_enable_irq(priv->irq);
1412	
1413	  /* 12. Signal carrier on to the network stack */
1414	
1415	  if (priv->link_up)
1416	    {
1417	      netdev_lower_carrier_on(dev);
1418	    }
1419	
1420	  ethinfo("ifup done: %d Mbps %s duplex, link=%s\n",
1421	          priv->speed, priv->duplex ? "Full" : "Half",
1422	          priv->link_up ? "up" : "down");
1423	
1424	  return OK;
1425	}
1426	
1427	/****************************************************************************
1428	 * Name: netdriver_ifdown
1429	 *
1430	 * Description:
1431	 *   OpenVela netdev_ops_s ifdown callback.  Stops DMA, disables MAC,
1432	 *   and disables interrupts.
1433	 *
1434	 * Reference: Manual §4.3
1435	 ****************************************************************************/
1436	
1437	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1438	{
1439	  FAR struct sg2000_eth_priv_s *priv =
1440	      (FAR struct sg2000_eth_priv_s *)dev;
1441	  uintptr_t gmac_base = priv->gmac_base;
1442	  uint32_t val;
1443	
1444	  up_disable_irq(priv->irq);
1445	
1446	  /* Stop TX and RX DMA */
1447	
1448	  val = getreg32(gmac_base + DMA_CONTROL);
1449	  putreg32(val & ~(DMA_CONTROL_ST | DMA_CONTROL_SR), gmac_base + DMA_CONTROL);
1450	
1451	  /* Disable MAC TX/RX */
1452	
1453	  val = getreg32(gmac_base + GMAC_CONTROL);
1454	  putreg32(val & ~(GMAC_CONTROL_TE | GMAC_CONTROL_RE),
1455	           gmac_base + GMAC_CONTROL);
1456	
1457	  /* Disable DMA interrupts */
1458	
1459	  putreg32(0, gmac_base + DMA_INTR_ENA);
1460	
1461	  /* Clear pending interrupts */
1462	
1463	  putreg32(DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
1464	
1465	  netdev_lower_carrier_off(dev);
1466	
1467	  priv->link_up = 0;
1468	
1469	  ethinfo("ifdown: interface stopped\n");
1470	
1471	  return OK;
1472	}
1473	
1474	/****************************************************************************
1475	 * Name: netdriver_transmit
1476	 *
1477	 * Description:
1478	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet via DMA.
1479	 *   The driver takes ownership of the netpkt and MUST free it after
1480	 *   TX completion (in tx_cleanup) or on error.
1481	 *
1482	 * Reference: Manual §5.1, §10.4
1483	 ****************************************************************************/
1484	
1485	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1486	                               FAR netpkt_t *pkt)
1487	{
1488	  FAR struct sg2000_eth_priv_s *priv =
1489	      (FAR struct sg2000_eth_priv_s *)dev;
1490	  unsigned int len = netpkt_getdatalen(dev, pkt);
1491	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1492	  const uint8_t *data;
1493	  unsigned int slot;
1494	  irqstate_t flags;
1495	  int ret;
1496	
1497	  if (len > SG2000_ETH_BUFSIZE)
1498	    {
1499	      etherr("TX packet too large: %u\n", len);
1500	      return -E2BIG;
1501	    }
1502	
1503	  /* Extract data from netpkt.  If fragmented, copy to tmp_buf;
1504	   * otherwise use pointer directly.
1505	   */
1506	
1507	  if (netpkt_is_fragmented(pkt))
1508	    {
1509	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1510	      data = tmp_buf;
1511	    }
1512	  else
1513	    {
1514	      data = netpkt_getdata(dev, pkt);
1515	      if (!data)
1516	        {
1517	          etherr("netpkt_getdata returned NULL\n");
1518	          return -EINVAL;
1519	        }
1520	    }
1521	
1522	  /* Transmit via DMA.
1523	   * On failure, do NOT free the netpkt — the upper half recycles it.
1524	   */
1525	
1526	  ret = hw_transmit(priv, data, len);
1527	  if (ret < 0)
1528	    {
1529	      etherr("hw_transmit failed: %d\n", ret);
1530	      return ret;
1531	    }
1532	
1533	  /* Track the netpkt: hw_transmit advanced tx_cur, so the in-flight
1534	   * slot is (tx_cur - 1).
1535	   */
1536	
1537	  flags = up_irq_save();
1538	  slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1539	  priv->tx_pkt[slot] = pkt;
1540	  up_irq_restore(flags);
1541	
1542	  return OK;
1543	}
1544	
1545	/****************************************************************************
1546	 * Name: netdriver_receive
1547	 *
1548	 * Description:
1549	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1550	 *   netdev_lower_rxready() was signaled.  Returns one received packet,
1551	 *   or NULL if no more packets are available.
1552	 *
1553	 * Reference: Manual §6, §10.5
1554	 ****************************************************************************/
1555	
1556	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1557	{
1558	  FAR struct sg2000_eth_priv_s *priv =
1559	      (FAR struct sg2000_eth_priv_s *)dev;
1560	  FAR netpkt_t *pkt = NULL;
1561	  struct sg2000_dma_desc_s *desc;
1562	  uintptr_t gmac_base = priv->gmac_base;
1563	  uint32_t status;
1564	  int frame_len;
1565	  int ret;
1566	
1567	  desc = &priv->rx_desc[priv->rx_cur];
1568	
1569	  /* Invalidate descriptor cache line to read DMA-written status */
1570	
1571	  dcache_invalidate_range((uintptr_t)desc,
1572	                          (uintptr_t)desc +
1573	                          sizeof(struct sg2000_dma_desc_s));
1574	
1575	  /* Check if DMA still owns the descriptor (no packet ready) */
1576	
1577	  if (desc->des0 & RDES0_OWN)
1578	    {
1579	      return NULL;
1580	    }
1581	
1582	  status = desc->des0;
1583	
1584	  /* Check for receive errors */
1585	
1586	  if (status & RDES0_ERROR_SUMMARY)
1587	    {
1588	      etherr("RX error status=0x%08" PRIX32 "\n", status);
1589	      goto refill;
1590	    }
1591	
1592	  /* Verify we got a complete frame (first AND last descriptor) */
1593	
1594	  if (!(status & RDES0_FIRST_DESCRIPTOR) ||
1595	      !(status & RDES0_LAST_DESCRIPTOR))
1596	    {
1597	      ethwarn("RX incomplete frame, status=0x%08" PRIX32 "\n", status);
1598	      goto refill;
1599	    }
1600	
1601	  /* Get frame length (includes 4-byte FCS which we strip) */
1602	
1603	  frame_len = (int)((status & RDES0_FRAME_LEN_MASK) >> RDES0_FRAME_LEN_SHIFT)
1604	              - ETH_FCSSLEN;
1605	
1606	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1607	    {
1608	      ethwarn("RX invalid frame length: %d\n", frame_len);
1609	      goto refill;
1610	    }
1611	
1612	  /* Invalidate RX data buffer to read DMA-written data */
1613	
1614	  dcache_invalidate_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1615	                          (uintptr_t)priv->rx_buf[priv->rx_cur] +
1616	                          RX_BUF_SIZE);
1617	
1618	  /* Allocate a netpkt for the received data */
1619	
1620	  pkt = netpkt_alloc(dev, NETPKT_RX);
1621	  if (!pkt)
1622	    {
1623	      etherr("netpkt_alloc failed\n");
1624	      goto refill;
1625	    }
1626	
1627	  /* Copy data from DMA buffer into netpkt */
1628	
1629	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1630	  if (ret < 0)
1631	    {
1632	      etherr("netpkt_copyin failed: %d\n", ret);
1633	      netpkt_free(dev, pkt, NETPKT_RX);
1634	      pkt = NULL;
1635	      goto refill;
1636	    }
1637	
1638	  ethinfo("RX: %d bytes desc[%u]\n", frame_len, priv->rx_cur);
1639	
1640	refill:
1641	  /* Return descriptor to DMA: set OWN=1, restore buffer address.
1642	   * Preserve END_RING bit for the last descriptor in des1.
1643	   */
1644	
1645	  desc->des0 = RDES0_OWN;
1646	  desc->des1 = (RX_BUF_SIZE & RDES1_BUFFER1_SIZE_MASK) |
1647	               ((priv->rx_cur == (RX_RING_SIZE - 1)) ? RDES1_END_RING : 0);
1648	  desc->des2 = priv->rx_buf_phys[priv->rx_cur];
1649	
1650	  /* Flush RX buffer before handing it back to DMA */
1651	
1652	  dcache_flush_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1653	                     (uintptr_t)priv->rx_buf[priv->rx_cur] + RX_BUF_SIZE);
1654	
1655	  /* Write back descriptor so DMA sees OWN=1 */
1656	
1657	  dcache_clean_range((uintptr_t)desc,
1658	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1659	
1660	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1661	  rx_doorbell(gmac_base);
1662	
1663	  return pkt;
1664	}
