1027	/****************************************************************************
1028	 * Name: gmac_set_speed_duplex
1029	 *
1030	 * Description:
1031	 *   Configure GMAC speed and duplex mode based on PHY negotiation result.
1032	 *
1033	 * Reference: Manual §10.9
1034	 ****************************************************************************/
1035	
1036	static void gmac_set_speed_duplex(uintptr_t gmac_base, int speed, int duplex)
1037	{
1038	  uint32_t val;
1039	
1040	  val = getreg32(gmac_base + GMAC_CONTROL);
1041	
1042	  /* Clear speed and duplex bits */
1043	
1044	  val &= ~(GMAC_CONTROL_FES | GMAC_CONTROL_DM);
1045	
1046	  /* Set speed: FES=1 for 100Mbps, FES=0 for 10Mbps */
1047	
1048	  if (speed == 100)
1049	    {
1050	      val |= GMAC_CONTROL_FES;
1051	    }
1052	
1053	  /* Set duplex: DM=1 for full duplex */
1054	
1055	  if (duplex)
1056	    {
1057	      val |= GMAC_CONTROL_DM;
1058	    }
1059	
1060	  putreg32(val, gmac_base + GMAC_CONTROL);
1061	}
