1063	/****************************************************************************
1064	 * Private Functions — DMA Doorbell
1065	 *
1066	 * Writing any value to DMA_XMT_POLL_DEMAND / DMA_RCV_POLL_DEMAND
1067	 * triggers the DMA engine to re-fetch descriptors from the ring.
1068	 *
1069	 * Reference: Manual §2.3, §10.4, §10.5
1070	 ****************************************************************************/
1071	
1072	static void tx_doorbell(uintptr_t gmac_base)
1073	{
1074	  putreg32(0, gmac_base + DMA_XMT_POLL_DEMAND);
1075	}
1076	
1077	static void rx_doorbell(uintptr_t gmac_base)
1078	{
1079	  putreg32(0, gmac_base + DMA_RCV_POLL_DEMAND);
1080	}
1081	
1082	/****************************************************************************
1083	 * Private Functions — Hardware Transmit
1084	 *
1085	 * Prepares a TX descriptor, copies data to the DMA buffer, and signals
1086	 * the DMA engine to transmit.
1087	 *
1088	 * Reference: Manual §5.2, §10.4
1089	 ****************************************************************************/
1090	
1091	static int hw_transmit(struct sg2000_eth_priv_s *priv,
1092	                       const uint8_t *data, unsigned int len)
1093	{
1094	  uintptr_t gmac_base = priv->gmac_base;
1095	  unsigned int idx = priv->tx_cur;
1096	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
1097	  irqstate_t flags;
1098	
1099	  /* Check if ring is full */
1100	
1101	  if (desc->des0 & TDES0_OWN)
1102	    {
1103	      return -EBUSY;
1104	    }
1105	
1106	  /* Copy data to pre-allocated TX DMA buffer */
1107	
1108	  memcpy(priv->tx_buf[idx], data, len);
1109	
1110	  /* Write back TX buffer so DMA can see packet data */
1111	
1112	  dcache_clean_range((uintptr_t)priv->tx_buf[idx],
1113	                     (uintptr_t)priv->tx_buf[idx] + len);
1114	
1115	  /* Fill descriptor (basic format, 16 bytes):
1116	   *   des0: OWN + IC
1117	   *   des1: buffer size + FS + LS + END_RING + IC
1118	   *   des2: buffer physical address
1119	   */
1120	
1121	  desc->des2 = priv->tx_buf_phys[idx];
1122	  desc->des1 = (len & TDES1_BUFFER1_SIZE_MASK) |
1123	               TDES1_FIRST_SEGMENT | TDES1_LAST_SEGMENT |
1124	               TDES1_END_RING | TDES1_INTERRUPT;
1125	
1126	  /* Memory barrier: ensure descriptor writes are visible to DMA
1127	   * before setting OWN=1.
1128	   */
1129	
1130	  dcache_clean_range((uintptr_t)desc,
1131	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1132	  __asm__ volatile ("fence w,w" ::: "memory");
1133	
1134	  /* Give ownership to DMA.  IC and END_RING are set in des1 above. */
1135	
1136	  desc->des0 = TDES0_OWN;
1137	
1138	  dcache_clean_range((uintptr_t)desc,
1139	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1140	
1141	  /* Advance TX pointer and ring doorbell */
1142	
1143	  flags = up_irq_save();
1144	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1145	  tx_doorbell(gmac_base);
1146	  up_irq_restore(flags);
1147	
1148	  ethinfo("TX: %u bytes desc[%u] des0=0x%08" PRIX32
1149	          " des1=0x%08" PRIX32 " des2=0x%08" PRIX32
1150	          " dma_status=0x%08" PRIX32 "\n",
1151	          len, idx, desc->des0, desc->des1, desc->des2,
1152	          getreg32(gmac_base + DMA_STATUS));
1153	
1154	  return OK;
1155	}
1156	
1157	/****************************************************************************
1158	 * Private Functions — TX Cleanup
1159	 *
1160	 * Frees completed TX packets by walking from dirty_tx to cur_tx.
1161	 * Called from ISR on TX Complete interrupt.
1162	 *
1163	 * Reference: Manual §5.3, §10.4 step 7
1164	 ****************************************************************************/
1165	
1166	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
1167	{
1168	  irqstate_t flags = up_irq_save();
1169	
1170	  while (priv->tx_dirty != priv->tx_cur)
1171	    {
1172	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
1173	
1174	      /* Invalidate descriptor cache line to read DMA-written status */
1175	
1176	      dcache_invalidate_range((uintptr_t)desc,
1177	                              (uintptr_t)desc +
1178	                              sizeof(struct sg2000_dma_desc_s));
1179	
1180	      if (desc->des0 & TDES0_OWN)
1181	        {
1182	          break;  /* Still owned by DMA */
1183	        }
1184	
1185	      /* Check for TX errors */
1186	
1187	      if (desc->des0 & TDES0_ERROR_SUMMARY)
1188	        {
1189	          etherr("TX error desc[%u] status=0x%08" PRIX32 "\n",
1190	                 priv->tx_dirty, desc->des0);
1191	        }
1192	
1193	      /* Free the tracked netpkt and notify upper half */
1194	
1195	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
1196	        {
1197	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
1198	          priv->tx_pkt[priv->tx_dirty] = NULL;
1199	          netdev_lower_txdone(&priv->dev);
1200	        }
1201	
1202	      /* Clear descriptor for reuse, END_RING=1 on all (CV181x convention) */
1203	
1204	      desc->des0 = 0;
1205	      desc->des1 = TDES1_END_RING;
1206	
1207	      dcache_clean_range((uintptr_t)desc,
1208	                         (uintptr_t)desc +
1209	                         sizeof(struct sg2000_dma_desc_s));
1210	
1211	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1212	    }
1213	
1214	  up_irq_restore(flags);
1215	}
1216	
1217	/****************************************************************************
1218	 * Private Functions — Interrupt Service Routine
1219	 *
1220	 * Reads DMA_STATUS to determine interrupt cause and dispatches accordingly.
1221	 * All DMA status bits are write-1-to-clear.
1222	 *
1223	 * Reference: Manual §7, §10.6
1224	 ****************************************************************************/
1225	
1226	static int sg2000_eth_isr(int irq, void *context, void *arg)
1227	{
1228	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1229	  uintptr_t gmac_base = priv->gmac_base;
1230	  uint32_t status;
1231	  uint32_t mac_status;
1232	
1233	  /* Read and clear MAC interrupts (if any) */
1234	
1235	  mac_status = getreg32(gmac_base + GMAC_INT_STATUS);
1236	  if (mac_status)
1237	    {
1238	      putreg32(mac_status, gmac_base + GMAC_INT_STATUS);
1239	    }
1240	
1241	  /* Read DMA status masked by enabled interrupts */
1242	
1243	  status = getreg32(gmac_base + DMA_STATUS) &
1244	           getreg32(gmac_base + DMA_INTR_ENA);
1245	
1246	  if (!status)
1247	    {
1248	      return OK;
1249	    }
1250	
1251	  ethinfo("ISR: dma_status=0x%08" PRIX32 "\n", status);
1252	
1253	  /* Write-1-to-clear the status bits */
1254	
1255	  putreg32(status & DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
1256	
1257	  /* Handle normal interrupts */
1258	
1259	  if (status & DMA_STATUS_NIS)
1260	    {
1261	      /* Receive interrupt: notify upper half */
1262	
1263	      if (status & DMA_STATUS_RI)
1264	        {
1265	          netdev_lower_rxready(&priv->dev);
1266	        }
1267	
1268	      /* Transmit complete: clean up descriptors */
1269	
1270	      if (status & DMA_STATUS_TI)
1271	        {
1272	          tx_cleanup(priv);
1273	        }
1274	    }
1275	
1276	  /* Handle abnormal interrupts */
1277	
1278	  if (status & DMA_STATUS_AIS)
1279	    {
1280	      if (status & DMA_STATUS_FBI)
1281	        {
1282	          etherr("Fatal Bus Error! bus_mode=0x%08" PRIX32
1283	                 " dma_status=0x%08" PRIX32 "\n",
1284	                 getreg32(gmac_base + DMA_BUS_MODE), status);
1285	        }
1286	
1287	      if (status & DMA_STATUS_TU)
1288	        {
1289	          ethwarn("TX Buffer Unavailable\n");
1290	        }
1291	
1292	      if (status & DMA_STATUS_RU)
1293	        {
1294	          ethwarn("RX Buffer Unavailable\n");
1295	        }
1296	
1297	      if (status & DMA_STATUS_TPS)
1298	        {
1299	          ethwarn("TX Process Stopped\n");
1300	        }
1301	
1302	      if (status & DMA_STATUS_RPS)
1303	        {
1304	          ethwarn("RX Process Stopped\n");
1305	        }
1306	
1307	      if (status & DMA_STATUS_OVF)
1308	        {
1309	          ethwarn("RX Overflow\n");
1310	        }
1311	
1312	      if (status & DMA_STATUS_UNF)
1313	        {
1314	          ethwarn("TX Underflow\n");
1315	        }
1316	    }
1317	
1318	  return OK;
1319	}
