1474	/****************************************************************************
1475	 * Name: netdriver_transmit
1476	 *
1477	 * Description:
1478	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet via DMA.
1479	 *   The driver takes ownership of the netpkt and MUST free it after
1480	 *   TX completion (in tx_cleanup) or on error.
1481	 *
1482	 * Reference: Manual §5.1, §10.4
1483	 ****************************************************************************/
1484	
1485	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1486	                               FAR netpkt_t *pkt)
1487	{
1488	  FAR struct sg2000_eth_priv_s *priv =
1489	      (FAR struct sg2000_eth_priv_s *)dev;
1490	  unsigned int len = netpkt_getdatalen(dev, pkt);
1491	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1492	  const uint8_t *data;
1493	  unsigned int slot;
1494	  irqstate_t flags;
1495	  int ret;
1496	
1497	  if (len > SG2000_ETH_BUFSIZE)
1498	    {
1499	      etherr("TX packet too large: %u\n", len);
1500	      return -E2BIG;
1501	    }
1502	
1503	  /* Extract data from netpkt.  If fragmented, copy to tmp_buf;
1504	   * otherwise use pointer directly.
1505	   */
1506	
1507	  if (netpkt_is_fragmented(pkt))
1508	    {
1509	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1510	      data = tmp_buf;
1511	    }
1512	  else
1513	    {
1514	      data = netpkt_getdata(dev, pkt);
1515	      if (!data)
1516	        {
1517	          etherr("netpkt_getdata returned NULL\n");
1518	          return -EINVAL;
1519	        }
1520	    }
1521	
1522	  /* Transmit via DMA.
1523	   * On failure, do NOT free the netpkt — the upper half recycles it.
1524	   */
1525	
1526	  ret = hw_transmit(priv, data, len);
1527	  if (ret < 0)
1528	    {
1529	      etherr("hw_transmit failed: %d\n", ret);
1530	      return ret;
1531	    }
1532	
1533	  /* Track the netpkt: hw_transmit advanced tx_cur, so the in-flight
1534	   * slot is (tx_cur - 1).
1535	   */
1536	
1537	  flags = up_irq_save();
1538	  slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1539	  priv->tx_pkt[slot] = pkt;
1540	  up_irq_restore(flags);
1541	
1542	  return OK;
1543	}
