1682	/****************************************************************************
1683	 * Name: sg2000_eth_initialize
1684	 *
1685	 * Description:
1686	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1687	 *   network stack as a netdev_lowerhalf_s device.
1688	 *
1689	 *   Called from board_late_initialize() during system bringup.
1690	 *
1691	 ****************************************************************************/
1692	
1693	int sg2000_eth_initialize(void)
1694	{
1695	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1696	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1697	  int ret;
1698	
1699	  if (g_eth_initialized)
1700	    {
1701	      return OK;
1702	    }
1703	
1704	  /* Initialize private data */
1705	
1706	  memset(priv, 0, sizeof(*priv));
1707	  priv->gmac_base = SG2000_GMAC_BASE;
1708	  priv->phy_base  = SG2000_EPHY_BASE;
1709	  priv->phy_top   = SG2000_EPHY_TOP;
1710	
1711	  /* Set default MAC address (should be replaced with eFuse/OTP value) */
1712	
1713	  priv->mac_addr[0] = 0x02;
1714	  priv->mac_addr[1] = 0x00;
1715	  priv->mac_addr[2] = 0x00;
1716	  priv->mac_addr[3] = 0x00;
1717	  priv->mac_addr[4] = 0x00;
1718	  priv->mac_addr[5] = 0x01;
1719	
1720	  /* Copy MAC address to the netdev structure */
1721	
1722	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1723	         IFHWADDRLEN);
1724	
1725	  /* Configure device quotas and operations.
1726	   * Total quota (TX + RX) must not exceed CONFIG_IOB_NBUFFERS.
1727	   * With CONFIG_IOB_NBUFFERS=64, we reserve 16 each (32 total).
1728	   */
1729	
1730	  dev->quota[NETPKT_TX] = 16;
1731	  dev->quota[NETPKT_RX] = 16;
1732	  dev->ops              = &g_ops;
1733	
1734	  /* Get the GMAC interrupt number */
1735	
1736	  priv->irq = SG2000_IRQ_GMAC;
1737	
1738	  /* Register with the OpenVela network stack */
1739	
1740	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1741	  if (ret < 0)
1742	    {
1743	      etherr("netdev_lower_register failed: %d\n", ret);
1744	      return ret;
1745	    }
1746	
1747	  /* Initially, carrier is off */
1748	
1749	  netdev_lower_carrier_off(dev);
1750	  g_eth_initialized = true;
1751	
1752	  ethinfo("SG2000 Ethernet driver registered as eth0\n");
1753	
1754	  /* Enable clocks so IRQ attach works */
1755	
1756	  gmac_clock_enable();
1757	
1758	  /* Attach interrupt handler */
1759	
1760	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1761	  if (ret < 0)
1762	    {
1763	      etherr("irq_attach failed: %d\n", ret);
1764	      return OK;  /* Driver is still registered, just no interrupts */
1765	    }
1766	
1767	  up_enable_irq(priv->irq);
1768	
1769	  ethinfo("IRQ %d enabled\n", priv->irq);
1770	
1771	  return OK;
1772	}
