1500	  const uint8_t *data;
1501	  irqstate_t flags;
1502	  int ret;
1503	
1504	  if (len > SG2000_ETH_BUFSIZE)
1505	    {
1506	      etherr("TX packet too large: %u\n", len);
1507	      return -E2BIG;
1508	    }
1509	
1510	  /* Extract data from netpkt.  If fragmented, copy to tmp_buf;
1511	   * otherwise use pointer directly.
1512	   */
1513	
1514	  if (netpkt_is_fragmented(pkt))
1515	    {
1516	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1517	      data = tmp_buf;
1518	    }
1519	  else
1520	    {
1521	      data = netpkt_getdata(dev, pkt);
1522	      if (!data)
1523	        {
1524	          etherr("netpkt_getdata returned NULL\n");
1525	          return -EINVAL;
1526	        }
1527	    }
1528	
1529	  /* Transmit via DMA.  Track the netpkt BEFORE calling hw_transmit
1530	   * (which advances tx_cur) so the ISR can't observe a half-committed
1531	   * slot.  The whole section runs with IRQs off to close the race
1532	   * between pkt store, cur advance, and ISR tx_cleanup.
1533	   *
1534	   * On failure, do NOT free the netpkt — the upper half recycles it.
1535	   */
1536	
1537	  flags = up_irq_save();
1538	  priv->tx_pkt[priv->tx_cur] = pkt;
1539	
1540	  ret = hw_transmit(priv, data, len);
1541	  if (ret < 0)
1542	    {
1543	      priv->tx_pkt[priv->tx_cur] = NULL;  /* Undo — slot not consumed */
1544	      up_irq_restore(flags);
