882	/****************************************************************************
883	 * Private Functions — MAC Address Configuration
884	 *
885	 * Reference: Manual §4.4 Step 6, §10.3 Phase 5.3
886	 ****************************************************************************/
887	
888	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
889	{
890	  uint32_t hi;
891	  uint32_t lo;
892	
893	  hi = ((uint32_t)mac[5] << 8) | (uint32_t)mac[4] | GMAC_HI_REG_AE;
894	  lo = ((uint32_t)mac[3] << 24) | ((uint32_t)mac[2] << 16) |
895	       ((uint32_t)mac[1] << 8)  | (uint32_t)mac[0];
896	
897	  putreg32(hi, gmac_base + GMAC_MAC_ADDR0_HIGH);
898	  putreg32(lo, gmac_base + GMAC_MAC_ADDR0_LOW);
899	
900	  ethinfo("MAC addr set: %02x:%02x:%02x:%02x:%02x:%02x\n",
901	          mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
902	}
903	
904	/****************************************************************************
905	 * Private Functions — MAC Core and DMA Initialization
906	 *
907	 * Performs the full hardware initialization sequence:
908	 *   - DMA bus mode and AXI configuration
909	 *   - MAC core init (GMAC_CONTROL, interrupt mask, frame filter)
910	 *   - DMA operation mode (Store-and-Forward)
911	 *   - Interrupt enable
912	 *   - Write descriptor base addresses
913	 *   - Start DMA TX and RX
914	 *
915	 * Reference: Manual §10.3 Phase 2, 5, 6, 7
916	 ****************************************************************************/
917	
918	static int hw_setup(struct sg2000_eth_priv_s *priv)
919	{
920	  uintptr_t gmac_base = priv->gmac_base;
921	  uint32_t val;
922	
923	  /* --- Phase 2: DMA software reset --- */
924	
925	  if (dma_soft_reset(gmac_base) < 0)
926	    {
927	      return -ETIMEDOUT;
928	    }
929	
930	  /* --- Phase 2.2: Configure DMA Bus Mode ---
931	   * PBL=8, RPBL=8, FB=1 (fixed burst), USP=1 (separate PBL),
932	   * AAL=1 (address-aligned beats).  ATDS is NOT set (basic descriptors).
933	   * Use explicit constants; (DMA_PBL_8 & 0x3f) would be 0 (PBL field is
934	   * at bits 8-13, masking with 0x3f gives 0).
935	   */
936	
937	  val = DMA_PBL_8 | ((3 << DMA_RPBL_SHIFT) & DMA_RPBL_MASK) |
938	        DMA_FB | DMA_USP | DMA_AAL;
939	  putreg32(val, gmac_base + DMA_BUS_MODE);
940	
941	  /* --- Phase 2.3: Configure AXI bus ---
942	   * WR_OSR_LMT=1, RD_OSR_LMT=2, BLEN support for 4/8/16 beats.
943	   */
944	
945	  putreg32((1 << DMA_AXI_WR_OSR_LMT_SHIFT) |
946	           (2 << DMA_AXI_RD_OSR_LMT_SHIFT) |
947	           (0xf << DMA_AXI_BLEN_SHIFT),
948	           gmac_base + DMA_AXI_BUS_MODE);
949	
950	  ethinfo("DMA: bus_mode=0x%08" PRIX32 " axi=0x%08" PRIX32 "\n",
951	          getreg32(gmac_base + DMA_BUS_MODE),
952	          getreg32(gmac_base + DMA_AXI_BUS_MODE));
953	
954	  /* --- Phase 5.1: Configure GMAC_CONTROL --- */
955	
956	  putreg32(GMAC_CORE_INIT, gmac_base + GMAC_CONTROL);
957	
958	  /* --- Phase 5.2: Configure GMAC_INT_MASK (disable all MAC interrupts,
959	   *   use DMA interrupts only) ---
960	   */
961	
962	  putreg32(GMAC_INT_DEFAULT_MASK, gmac_base + GMAC_INT_MASK);
963	
964	  /* --- Phase 5.4: Configure frame filter ---
965	   * Use promiscuous mode (PR) to accept all packets.  This matches the
966	   * old driver's setup and avoids MAC address filtering issues.
967	   */
968	
969	  putreg32(GMAC_FILTER_PR | GMAC_FILTER_HMC | GMAC_FILTER_PM,
970	           gmac_base + GMAC_FRAME_FILTER);
971	
972	  /* Clear VLAN tag */
973	
974	  putreg32(0, gmac_base + GMAC_VLAN_TAG);
975	
976	  /* Clear pending MAC and DMA interrupts */
977	
978	  putreg32(0xffffffff, gmac_base + GMAC_INT_STATUS);
979	  putreg32(DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
980	
981	  /* --- Phase 5.5: Enable MAC TX and RX --- */
982	
983	  val = getreg32(gmac_base + GMAC_CONTROL);
984	  putreg32(val | GMAC_CONTROL_TE | GMAC_CONTROL_RE, gmac_base + GMAC_CONTROL);
985	
986	  /* --- Phase 6.1: Configure DMA operation mode ---
987	   * RSF=1 (RX Store-and-Forward), TSF=1 (TX Store-and-Forward),
988	   * OSF=1 (Operate on Second Frame), RTC=64, TTC=64.
989	   */
990	
991	  val = getreg32(gmac_base + DMA_CONTROL);
992	  val |= DMA_CONTROL_RSF | DMA_CONTROL_TSF | DMA_CONTROL_OSF |
993	         DMA_CONTROL_RTC_64 | DMA_CONTROL_TTC_64;
994	  putreg32(val, gmac_base + DMA_CONTROL);
995	
996	  /* --- Phase 6.2: Enable DMA interrupts --- */
997	
998	  putreg32(DMA_INTR_DEFAULT_MASK, gmac_base + DMA_INTR_ENA);
999	
1000	  /* --- Phase 7.1: Write descriptor base addresses --- */
1001	
1002	  putreg32(priv->tx_desc_phys, gmac_base + DMA_TX_BASE_ADDR);
1003	  putreg32(priv->rx_desc_phys, gmac_base + DMA_RCV_BASE_ADDR);
1004	
1005	  /* --- Phase 7.2-7.3: Start DMA TX and RX ---
1006	   * Write ST first, then SR separately with a delay.  The hardware
1007	   * may ignore SR if written simultaneously with ST.
1008	   */
1009	
1010	  val = getreg32(gmac_base + DMA_CONTROL);
1011	  putreg32(val | DMA_CONTROL_ST, gmac_base + DMA_CONTROL);
1012	  up_udelay(10);
1013	
1014	  val = getreg32(gmac_base + DMA_CONTROL);
1015	  putreg32(val | DMA_CONTROL_SR, gmac_base + DMA_CONTROL);
1016	  up_udelay(10);
1017	
1018	  ethinfo("MAC/DMA started: gmac_ctrl=0x%08" PRIX32
1019	          " dma_ctrl=0x%08" PRIX32 " dma_status=0x%08" PRIX32
1020	          " dma_intr=0x%08" PRIX32 "\n",
1021	          getreg32(gmac_base + GMAC_CONTROL),
1022	          getreg32(gmac_base + DMA_CONTROL),
1023	          getreg32(gmac_base + DMA_STATUS),
1024	          getreg32(gmac_base + DMA_INTR_ENA));
1025	
1026	  return OK;
1027	}
