1029	/****************************************************************************
1030	 * Name: gmac_set_speed_duplex
1031	 *
1032	 * Description:
1033	 *   Configure GMAC speed and duplex mode based on PHY negotiation result.
1034	 *
1035	 * Reference: Manual §10.9
1036	 ****************************************************************************/
1037	
1038	static void gmac_set_speed_duplex(uintptr_t gmac_base, int speed, int duplex)
1039	{
1040	  uint32_t val;
1041	
1042	  val = getreg32(gmac_base + GMAC_CONTROL);
1043	
1044	  /* Clear speed and duplex bits */
1045	
1046	  val &= ~(GMAC_CONTROL_FES | GMAC_CONTROL_DM);
1047	
1048	  /* Set speed: FES=1 for 100Mbps, FES=0 for 10Mbps */
1049	
1050	  if (speed == 100)
1051	    {
1052	      val |= GMAC_CONTROL_FES;
1053	    }
1054	
1055	  /* Set duplex: DM=1 for full duplex */
1056	
1057	  if (duplex)
1058	    {
1059	      val |= GMAC_CONTROL_DM;
1060	    }
1061	
1062	  putreg32(val, gmac_base + GMAC_CONTROL);
1063	}
