1065	/****************************************************************************
1066	 * Private Functions — DMA Doorbell
1067	 *
1068	 * Writing any value to DMA_XMT_POLL_DEMAND / DMA_RCV_POLL_DEMAND
1069	 * triggers the DMA engine to re-fetch descriptors from the ring.
1070	 *
1071	 * Reference: Manual §2.3, §10.4, §10.5
1072	 ****************************************************************************/
1073	
1074	static void tx_doorbell(uintptr_t gmac_base)
1075	{
1076	  putreg32(0, gmac_base + DMA_XMT_POLL_DEMAND);
1077	}
1078	
1079	static void rx_doorbell(uintptr_t gmac_base)
1080	{
1081	  putreg32(0, gmac_base + DMA_RCV_POLL_DEMAND);
1082	}
1083	
1084	/****************************************************************************
1085	 * Private Functions — Hardware Transmit
1086	 *
1087	 * Prepares a TX descriptor, copies data to the DMA buffer, and signals
1088	 * the DMA engine to transmit.
1089	 *
1090	 * Reference: Manual §5.2, §10.4
1091	 ****************************************************************************/
1092	
1093	static int hw_transmit(struct sg2000_eth_priv_s *priv,
1094	                       const uint8_t *data, unsigned int len)
1095	{
1096	  uintptr_t gmac_base = priv->gmac_base;
1097	  unsigned int idx = priv->tx_cur;
1098	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
1099	  irqstate_t flags;
1100	
1101	  /* Check if ring is full */
1102	
1103	  if (desc->des0 & TDES0_OWN)
1104	    {
1105	      return -EBUSY;
1106	    }
1107	
1108	  /* Copy data to pre-allocated TX DMA buffer */
1109	
1110	  memcpy(priv->tx_buf[idx], data, len);
1111	
1112	  /* Write back TX buffer so DMA can see packet data */
1113	
1114	  dcache_clean_range((uintptr_t)priv->tx_buf[idx],
1115	                     (uintptr_t)priv->tx_buf[idx] + len);
1116	
1117	  /* Fill descriptor (basic format, 16 bytes):
1118	   *   des0: OWN + IC
1119	   *   des1: buffer size + FS + LS + END_RING + IC
1120	   *   des2: buffer physical address
1121	   */
1122	
1123	  desc->des2 = priv->tx_buf_phys[idx];
1124	  desc->des1 = (len & TDES1_BUFFER1_SIZE_MASK) |
1125	               TDES1_FIRST_SEGMENT | TDES1_LAST_SEGMENT |
1126	               TDES1_END_RING | TDES1_INTERRUPT;
1127	
1128	  /* Memory barrier: ensure descriptor writes are visible to DMA
1129	   * before setting OWN=1.
1130	   */
1131	
1132	  dcache_clean_range((uintptr_t)desc,
1133	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1134	  __asm__ volatile ("fence w,w" ::: "memory");
1135	
1136	  /* Give ownership to DMA.  IC and END_RING are set in des1 above. */
1137	
1138	  desc->des0 = TDES0_OWN;
1139	
1140	  dcache_clean_range((uintptr_t)desc,
1141	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1142	
1143	  /* Advance TX pointer and ring doorbell */
1144	
1145	  flags = up_irq_save();
1146	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1147	  tx_doorbell(gmac_base);
1148	  up_irq_restore(flags);
1149	
1150	  ethinfo("TX: %u bytes desc[%u] des0=0x%08" PRIX32
1151	          " des1=0x%08" PRIX32 " des2=0x%08" PRIX32
1152	          " dma_status=0x%08" PRIX32 "\n",
1153	          len, idx, desc->des0, desc->des1, desc->des2,
1154	          getreg32(gmac_base + DMA_STATUS));
1155	
1156	  return OK;
1157	}
1158	
1159	/****************************************************************************
1160	 * Private Functions — TX Cleanup
1161	 *
1162	 * Frees completed TX packets by walking from dirty_tx to cur_tx.
1163	 * Called from ISR on TX Complete interrupt.
1164	 *
1165	 * Reference: Manual §5.3, §10.4 step 7
1166	 ****************************************************************************/
1167	
1168	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
1169	{
1170	  irqstate_t flags = up_irq_save();
1171	
1172	  while (priv->tx_dirty != priv->tx_cur)
1173	    {
1174	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
1175	
1176	      /* Invalidate descriptor cache line to read DMA-written status */
1177	
1178	      dcache_invalidate_range((uintptr_t)desc,
1179	                              (uintptr_t)desc +
1180	                              sizeof(struct sg2000_dma_desc_s));
1181	
1182	      if (desc->des0 & TDES0_OWN)
1183	        {
1184	          break;  /* Still owned by DMA */
1185	        }
1186	
1187	      /* Check for TX errors */
1188	
1189	      if (desc->des0 & TDES0_ERROR_SUMMARY)
1190	        {
1191	          etherr("TX error desc[%u] status=0x%08" PRIX32 "\n",
1192	                 priv->tx_dirty, desc->des0);
1193	        }
1194	
1195	      /* Free the tracked netpkt and notify upper half */
1196	
1197	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
1198	        {
1199	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
1200	          priv->tx_pkt[priv->tx_dirty] = NULL;
1201	          netdev_lower_txdone(&priv->dev);
1202	        }
1203	
1204	      /* Clear descriptor for reuse, END_RING=1 on all (CV181x convention) */
1205	
1206	      desc->des0 = 0;
1207	      desc->des1 = TDES1_END_RING;
1208	
1209	      dcache_clean_range((uintptr_t)desc,
1210	                         (uintptr_t)desc +
1211	                         sizeof(struct sg2000_dma_desc_s));
1212	
1213	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1214	    }
1215	
1216	  up_irq_restore(flags);
1217	}
1218	
1219	/****************************************************************************
1220	 * Private Functions — Interrupt Service Routine
1221	 *
1222	 * Reads DMA_STATUS to determine interrupt cause and dispatches accordingly.
1223	 * All DMA status bits are write-1-to-clear.
1224	 *
1225	 * Reference: Manual §7, §10.6
1226	 ****************************************************************************/
1227	
1228	static int sg2000_eth_isr(int irq, void *context, void *arg)
1229	{
1230	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1231	  uintptr_t gmac_base = priv->gmac_base;
1232	  uint32_t status;
1233	  uint32_t mac_status;
1234	
1235	  /* Read and clear MAC interrupts (if any) */
1236	
1237	  mac_status = getreg32(gmac_base + GMAC_INT_STATUS);
1238	  if (mac_status)
1239	    {
1240	      putreg32(mac_status, gmac_base + GMAC_INT_STATUS);
1241	    }
1242	
1243	  /* Read DMA status masked by enabled interrupts */
1244	
1245	  status = getreg32(gmac_base + DMA_STATUS) &
1246	           getreg32(gmac_base + DMA_INTR_ENA);
1247	
1248	  if (!status)
1249	    {
1250	      return OK;
1251	    }
1252	
1253	  ethinfo("ISR: dma_status=0x%08" PRIX32 "\n", status);
1254	
1255	  /* Write-1-to-clear the status bits */
1256	
1257	  putreg32(status & DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
1258	
1259	  /* Handle normal interrupts */
1260	
1261	  if (status & DMA_STATUS_NIS)
1262	    {
1263	      /* Receive interrupt: notify upper half */
1264	
1265	      if (status & DMA_STATUS_RI)
1266	        {
1267	          netdev_lower_rxready(&priv->dev);
1268	        }
1269	
1270	      /* Transmit complete: clean up descriptors */
1271	
1272	      if (status & DMA_STATUS_TI)
1273	        {
1274	          tx_cleanup(priv);
1275	        }
1276	    }
1277	
1278	  /* Handle abnormal interrupts */
1279	
1280	  if (status & DMA_STATUS_AIS)
1281	    {
1282	      if (status & DMA_STATUS_FBI)
1283	        {
1284	          etherr("Fatal Bus Error! bus_mode=0x%08" PRIX32
1285	                 " dma_status=0x%08" PRIX32 "\n",
1286	                 getreg32(gmac_base + DMA_BUS_MODE), status);
1287	        }
1288	
1289	      if (status & DMA_STATUS_TU)
1290	        {
1291	          ethwarn("TX Buffer Unavailable\n");
1292	        }
1293	
1294	      if (status & DMA_STATUS_RU)
1295	        {
1296	          ethwarn("RX Buffer Unavailable\n");
1297	        }
1298	
1299	      if (status & DMA_STATUS_TPS)
1300	        {
1301	          ethwarn("TX Process Stopped\n");
1302	        }
1303	
1304	      if (status & DMA_STATUS_RPS)
1305	        {
1306	          ethwarn("RX Process Stopped\n");
1307	        }
1308	
1309	      if (status & DMA_STATUS_OVF)
1310	        {
1311	          ethwarn("RX Overflow\n");
1312	        }
1313	
1314	      if (status & DMA_STATUS_UNF)
1315	        {
1316	          ethwarn("TX Underflow\n");
1317	        }
1318	    }
1319	
1320	  return OK;
1321	}
