1323	/****************************************************************************
1324	 * Name: netdriver_ifup
1325	 *
1326	 * Description:
1327	 *   OpenVela netdev_ops_s ifup callback.  Performs the full hardware
1328	 *   initialization sequence and brings the interface online.
1329	 *
1330	 * Reference: Manual §4.3, §10.3, §10.11
1331	 ****************************************************************************/
1332	
1333	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1334	{
1335	  FAR struct sg2000_eth_priv_s *priv =
1336	      (FAR struct sg2000_eth_priv_s *)dev;
1337	  int ret;
1338	
1339	  ethinfo("ifup begin\n");
1340	
1341	  /* 1. Enable clocks and deassert resets */
1342	
1343	  gmac_clock_enable();
1344	
1345	  /* 2. Set GMAC_CORE_INIT (includes PS=MII mode) before PHY operations */
1346	
1347	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONTROL);
1348	
1349	  /* 3. Initialize EPHY via APB */
1350	
1351	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1352	
1353	  /* 4. Verify MDIO communication with PHY */
1354	
1355	  ret = mdio_verify_phy(priv->gmac_base);
1356	  if (ret < 0)
1357	    {
1358	      etherr("PHY not responding: %d\n", ret);
1359	      return ret;
1360	    }
1361	
1362	  ethinfo("MDIO operational, mdio_addr=0x%08" PRIX32
1363	          " mdio_data=0x%08" PRIX32 "\n",
1364	          getreg32(priv->gmac_base + GMAC_MII_ADDR),
1365	          getreg32(priv->gmac_base + GMAC_MII_DATA));
1366	
1367	  /* 5. Run EPHY full analog tuning (requires operational MDIO) */
1368	
1369	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1370	
1371	  /* 6. Allocate DMA resources (once) */
1372	
1373	  ret = alloc_dma(priv);
1374	  if (ret < 0)
1375	    {
1376	      etherr("alloc_dma failed: %d\n", ret);
1377	      return ret;
1378	    }
1379	
1380	  /* 7. Initialize descriptor rings */
1381	
1382	  init_desc_rings(priv);
1383	
1384	  /* 8. Set MAC address */
1385	
1386	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1387	
1388	  /* 9. Configure PHY (auto-negotiation) BEFORE starting DMA.
1389	   *    Starting DMA while the PHY is in reset causes the TX path to
1390	   *    stall (frames held in FIFO with no RMII link) and the RX path
1391	   *    to pick up garbage from an unstable RMII interface.
1392	   */
1393	
1394	  ret = phy_config_init(priv);
1395	  if (ret < 0)
1396	    {
1397	      etherr("PHY config failed: %d\n", ret);
1398	      return ret;
1399	    }
1400	
1401	  /* Apply negotiated speed/duplex to GMAC before DMA start */
1402	
1403	  gmac_set_speed_duplex(priv->gmac_base, priv->speed, priv->duplex);
1404	
1405	  /* 10. Hardware setup: DMA reset, MAC core, DMA mode, start DMA.
1406	   *    Performed AFTER PHY is ready — clean RMII link and stable speed.
1407	   */
1408	
1409	  ret = hw_setup(priv);
1410	  if (ret < 0)
1411	    {
1412	      etherr("hw_setup failed: %d\n", ret);
1413	      return ret;
1414	    }
1415	
1416	  /* 11. Ring RX doorbell and enable interrupts (last, after all HW init) */
1417	
1418	  rx_doorbell(priv->gmac_base);
1419	  up_enable_irq(priv->irq);
1420	
1421	  /* 12. Signal carrier on to the network stack (if link detected) */
1422	
1423	  if (priv->link_up)
1424	    {
1425	      netdev_lower_carrier_on(dev);
1426	    }
1427	
1428	  ethinfo("ifup done: %d Mbps %s duplex, link=%s\n",
1429	          priv->speed, priv->duplex ? "Full" : "Half",
1430	          priv->link_up ? "up" : "down");
1431	
1432	  return OK;
1433	}
1434	
1435	/****************************************************************************
1436	 * Name: netdriver_ifdown
1437	 *
1438	 * Description:
1439	 *   OpenVela netdev_ops_s ifdown callback.  Stops DMA, disables MAC,
1440	 *   and disables interrupts.
1441	 *
1442	 * Reference: Manual §4.3
1443	 ****************************************************************************/
1444	
1445	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1446	{
1447	  FAR struct sg2000_eth_priv_s *priv =
1448	      (FAR struct sg2000_eth_priv_s *)dev;
1449	  uintptr_t gmac_base = priv->gmac_base;
1450	  uint32_t val;
1451	
1452	  up_disable_irq(priv->irq);
1453	
1454	  /* Stop TX and RX DMA */
1455	
1456	  val = getreg32(gmac_base + DMA_CONTROL);
1457	  putreg32(val & ~(DMA_CONTROL_ST | DMA_CONTROL_SR), gmac_base + DMA_CONTROL);
1458	
1459	  /* Disable MAC TX/RX */
1460	
1461	  val = getreg32(gmac_base + GMAC_CONTROL);
1462	  putreg32(val & ~(GMAC_CONTROL_TE | GMAC_CONTROL_RE),
1463	           gmac_base + GMAC_CONTROL);
1464	
1465	  /* Disable DMA interrupts */
1466	
1467	  putreg32(0, gmac_base + DMA_INTR_ENA);
1468	
1469	  /* Clear pending interrupts */
1470	
1471	  putreg32(DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
1472	
1473	  netdev_lower_carrier_off(dev);
1474	
1475	  priv->link_up = 0;
1476	
1477	  ethinfo("ifdown: interface stopped\n");
1478	
1479	  return OK;
1480	}
