1482	/****************************************************************************
1483	 * Name: netdriver_transmit
1484	 *
1485	 * Description:
1486	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet via DMA.
1487	 *   The driver takes ownership of the netpkt and MUST free it after
1488	 *   TX completion (in tx_cleanup) or on error.
1489	 *
1490	 * Reference: Manual §5.1, §10.4
1491	 ****************************************************************************/
1492	
1493	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1494	                               FAR netpkt_t *pkt)
1495	{
1496	  FAR struct sg2000_eth_priv_s *priv =
1497	      (FAR struct sg2000_eth_priv_s *)dev;
1498	  unsigned int len = netpkt_getdatalen(dev, pkt);
1499	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1500	  const uint8_t *data;
1501	  irqstate_t flags;
1502	  int ret;
1503	
1504	  if (len > SG2000_ETH_BUFSIZE)
1505	    {
1506	      etherr("TX packet too large: %u\n", len);
1507	      return -E2BIG;
1508	    }
1509	
1510	  /* Extract data from netpkt.  If fragmented, copy to tmp_buf;
1511	   * otherwise use pointer directly.
1512	   */
1513	
1514	  if (netpkt_is_fragmented(pkt))
1515	    {
1516	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1517	      data = tmp_buf;
1518	    }
1519	  else
1520	    {
1521	      data = netpkt_getdata(dev, pkt);
1522	      if (!data)
1523	        {
1524	          etherr("netpkt_getdata returned NULL\n");
1525	          return -EINVAL;
1526	        }
1527	    }
1528	
1529	  /* Transmit via DMA.  Track the netpkt BEFORE calling hw_transmit
1530	   * (which advances tx_cur) so the ISR can't observe a half-committed
1531	   * slot.  The whole section runs with IRQs off to close the race
1532	   * between pkt store, cur advance, and ISR tx_cleanup.
1533	   *
1534	   * On failure, do NOT free the netpkt — the upper half recycles it.
1535	   */
1536	
1537	  flags = up_irq_save();
1538	  priv->tx_pkt[priv->tx_cur] = pkt;
1539	
1540	  ret = hw_transmit(priv, data, len);
1541	  if (ret < 0)
1542	    {
1543	      priv->tx_pkt[priv->tx_cur] = NULL;  /* Undo — slot not consumed */
1544	      up_irq_restore(flags);
1545	      etherr("hw_transmit failed: %d\n", ret);
1546	      return ret;
1547	    }
1548	
1549	  up_irq_restore(flags);
1550	
1551	  return OK;
1552	}
1553	
1554	/****************************************************************************
1555	 * Name: netdriver_receive
1556	 *
1557	 * Description:
1558	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1559	 *   netdev_lower_rxready() was signaled.  Returns one received packet,
1560	 *   or NULL if no more packets are available.
1561	 *
1562	 * Reference: Manual §6, §10.5
1563	 ****************************************************************************/
1564	
1565	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1566	{
1567	  FAR struct sg2000_eth_priv_s *priv =
1568	      (FAR struct sg2000_eth_priv_s *)dev;
1569	  FAR netpkt_t *pkt = NULL;
1570	  struct sg2000_dma_desc_s *desc;
1571	  uintptr_t gmac_base = priv->gmac_base;
1572	  uint32_t status;
1573	  int frame_len;
1574	  int ret;
1575	
1576	  desc = &priv->rx_desc[priv->rx_cur];
1577	
1578	  /* Invalidate descriptor cache line to read DMA-written status */
1579	
1580	  dcache_invalidate_range((uintptr_t)desc,
1581	                          (uintptr_t)desc +
1582	                          sizeof(struct sg2000_dma_desc_s));
1583	
1584	  /* Check if DMA still owns the descriptor (no packet ready) */
1585	
1586	  if (desc->des0 & RDES0_OWN)
1587	    {
1588	      return NULL;
1589	    }
1590	
1591	  status = desc->des0;
1592	
1593	  /* Check for receive errors */
1594	
1595	  if (status & RDES0_ERROR_SUMMARY)
1596	    {
1597	      etherr("RX error status=0x%08" PRIX32 "\n", status);
1598	      goto refill;
1599	    }
1600	
1601	  /* Verify we got a complete frame (first AND last descriptor) */
1602	
1603	  if (!(status & RDES0_FIRST_DESCRIPTOR) ||
1604	      !(status & RDES0_LAST_DESCRIPTOR))
1605	    {
1606	      ethwarn("RX incomplete frame, status=0x%08" PRIX32 "\n", status);
1607	      goto refill;
1608	    }
1609	
1610	  /* Get frame length (includes 4-byte FCS which we strip) */
1611	
1612	  frame_len = (int)((status & RDES0_FRAME_LEN_MASK) >> RDES0_FRAME_LEN_SHIFT)
1613	              - ETH_FCSSLEN;
1614	
1615	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1616	    {
1617	      ethwarn("RX invalid frame length: %d\n", frame_len);
1618	      goto refill;
1619	    }
1620	
1621	  /* Invalidate RX data buffer to read DMA-written data */
1622	
1623	  dcache_invalidate_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1624	                          (uintptr_t)priv->rx_buf[priv->rx_cur] +
1625	                          RX_BUF_SIZE);
1626	
1627	  /* Allocate a netpkt for the received data */
1628	
1629	  pkt = netpkt_alloc(dev, NETPKT_RX);
1630	  if (!pkt)
1631	    {
1632	      etherr("netpkt_alloc failed\n");
1633	      goto refill;
1634	    }
1635	
1636	  /* Copy data from DMA buffer into netpkt */
1637	
1638	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1639	  if (ret < 0)
1640	    {
1641	      etherr("netpkt_copyin failed: %d\n", ret);
1642	      netpkt_free(dev, pkt, NETPKT_RX);
1643	      pkt = NULL;
1644	      goto refill;
1645	    }
1646	
1647	  ethinfo("RX: %d bytes desc[%u]\n", frame_len, priv->rx_cur);
1648	
1649	refill:
1650	  /* Return descriptor to DMA: set OWN=1, restore buffer address.
1651	   * Preserve END_RING bit for the last descriptor in des1.
1652	   */
1653	
1654	  desc->des0 = RDES0_OWN;
1655	  desc->des1 = (RX_BUF_SIZE & RDES1_BUFFER1_SIZE_MASK) |
1656	               ((priv->rx_cur == (RX_RING_SIZE - 1)) ? RDES1_END_RING : 0);
1657	  desc->des2 = priv->rx_buf_phys[priv->rx_cur];
1658	
1659	  /* Flush RX buffer before handing it back to DMA */
1660	
1661	  dcache_flush_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1662	                     (uintptr_t)priv->rx_buf[priv->rx_cur] + RX_BUF_SIZE);
1663	
1664	  /* Write back descriptor so DMA sees OWN=1 */
1665	
1666	  dcache_clean_range((uintptr_t)desc,
1667	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1668	
1669	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1670	  rx_doorbell(gmac_base);
1671	
1672	  return pkt;
1673	}
1674	
1675	/****************************************************************************
1676	 * Private Data — Operations Structure
1677	 ****************************************************************************/
1678	
1679	static const struct netdev_ops_s g_ops =
1680	{
1681	  netdriver_ifup,      /* ifup */
1682	  netdriver_ifdown,    /* ifdown */
1683	  netdriver_transmit,  /* transmit */
1684	  netdriver_receive    /* receive */
1685	};
