1691	/****************************************************************************
1692	 * Name: sg2000_eth_initialize
1693	 *
1694	 * Description:
1695	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1696	 *   network stack as a netdev_lowerhalf_s device.
1697	 *
1698	 *   Called from board_late_initialize() during system bringup.
1699	 *
1700	 ****************************************************************************/
1701	
1702	int sg2000_eth_initialize(void)
1703	{
1704	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1705	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1706	  int ret;
1707	
1708	  if (g_eth_initialized)
1709	    {
1710	      return OK;
1711	    }
1712	
1713	  /* Initialize private data */
1714	
1715	  memset(priv, 0, sizeof(*priv));
1716	  priv->gmac_base = SG2000_GMAC_BASE;
1717	  priv->phy_base  = SG2000_EPHY_BASE;
1718	  priv->phy_top   = SG2000_EPHY_TOP;
1719	
1720	  /* Set default MAC address (should be replaced with eFuse/OTP value) */
1721	
1722	  priv->mac_addr[0] = 0x02;
1723	  priv->mac_addr[1] = 0x00;
1724	  priv->mac_addr[2] = 0x00;
1725	  priv->mac_addr[3] = 0x00;
1726	  priv->mac_addr[4] = 0x00;
1727	  priv->mac_addr[5] = 0x01;
1728	
1729	  /* Copy MAC address to the netdev structure */
1730	
1731	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1732	         IFHWADDRLEN);
1733	
1734	  /* Configure device quotas and operations.
1735	   * Total quota (TX + RX) must not exceed CONFIG_IOB_NBUFFERS.
1736	   * With CONFIG_IOB_NBUFFERS=64, we reserve 16 each (32 total).
1737	   */
1738	
1739	  dev->quota[NETPKT_TX] = 16;
1740	  dev->quota[NETPKT_RX] = 16;
1741	  dev->ops              = &g_ops;
1742	
1743	  /* Get the GMAC interrupt number */
1744	
1745	  priv->irq = SG2000_IRQ_GMAC;
1746	
1747	  /* Register with the OpenVela network stack */
1748	
1749	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1750	  if (ret < 0)
1751	    {
1752	      etherr("netdev_lower_register failed: %d\n", ret);
1753	      return ret;
1754	    }
1755	
1756	  /* Initially, carrier is off */
1757	
1758	  netdev_lower_carrier_off(dev);
1759	  g_eth_initialized = true;
1760	
1761	  ethinfo("SG2000 Ethernet driver registered as eth0\n");
1762	
1763	  /* Attach interrupt handler (once).
1764	   * The IRQ is NOT enabled here — it is enabled at the end of
1765	   * netdriver_ifup() only after the hardware is fully configured.
1766	   */
1767	
1768	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1769	  if (ret < 0)
1770	    {
1771	      etherr("irq_attach failed: %d\n", ret);
1772	      return OK;  /* Driver is still registered, just no interrupts */
1773	    }
1774	
1775	  ethinfo("IRQ %d attached (not yet enabled)\n", priv->irq);
1776	
1777	  return OK;
1778	}
